        bid = max(bid, DAILY_SALARY * 0.58)
    elif need_level == 2:
        bid = max(bid, highest_prev + 3.0 if highest_prev > 0 else DAILY_SALARY * 0.82)
    elif need_level == 3:
        bid = max(bid, highest_prev + 8.0 if highest_prev > 0 else DAILY_SALARY * 0.96)

