def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opps = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opps:
        return min(budget, max(10, DAILY_SALARY * 0.3))
    # Collect previous bids from alive opponents
    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])
    # Determine base bid: median of previous bids or a safe low
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        median = sorted_bids[len(sorted_bids) // 2]
    else:
        median = DAILY_SALARY * 0.5
    # Desperation logic
    if hp <= 2 or no_water_days >= 2:
        target = max(median + 2, DAILY_SALARY * 0.85)
    elif hp <= 4:
        target = median + 1
    else:
        target = max(15, min(40, median * 0.6))
    # Adjust for supply: if supply low, bid higher
    if supply < 18:
        target *= 1.3
    elif supply > 22:
        target *= 0.8
    # Ensure affordability
    bid = min(budget, target)
    return max(0, int(bid))
